-- ─────────────────────────────────────────────────────────────────────────────
-- 007_industry_product_brains.sql
-- Creates industries and products tables and seeds them from zeach-brains JSONs.
-- Run in Supabase Dashboard → SQL Editor
-- ─────────────────────────────────────────────────────────────────────────────

-- ── Drop old tables if they exist (clean slate) ───────────────────────────────
DROP TABLE IF EXISTS public.products CASCADE;
DROP TABLE IF EXISTS public.industries CASCADE;

-- ── Industries ────────────────────────────────────────────────────────────────
CREATE TABLE public.industries (
  id              uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
  slug            text        NOT NULL UNIQUE,
  name            text        NOT NULL,
  valid_app_types text[]      NOT NULL DEFAULT '{}',
  brain           jsonb       NOT NULL DEFAULT '{}',
  sort_order      int         NOT NULL DEFAULT 0,
  created_at      timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE public.industries ENABLE ROW LEVEL SECURITY;
CREATE POLICY "industries_read_all" ON public.industries FOR SELECT USING (true);

-- ── Products (archetypes / app types) ─────────────────────────────────────────
CREATE TABLE public.products (
  id               uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
  archetype_id     text        NOT NULL UNIQUE,
  name             text        NOT NULL,
  description      text,
  valid_industries text[]      NOT NULL DEFAULT '{}',
  brain            jsonb       NOT NULL DEFAULT '{}',
  sort_order       int         NOT NULL DEFAULT 0,
  created_at       timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE public.products ENABLE ROW LEVEL SECURITY;
CREATE POLICY "products_read_all" ON public.products FOR SELECT USING (true);

-- ── Seed: industries ──────────────────────────────────────────────────────────
INSERT INTO public.industries (slug, name, valid_app_types, brain, sort_order) VALUES
  ('ai_technology', 'AI & Technology', ARRAY['AI Tool', 'Developer Tool', 'Dashboard SaaS']::text[], '{"industry_id": "ai_technology", "industry_name": "AI & Technology", "tone": {"primary": "intelligent, precise, forward-thinking", "secondary": "confident, minimal, empowering", "voice": "a brilliant engineer who communicates clearly — no hype, just capability", "avoid": "hype-heavy, buzzword-laden, overly casual, corporate fluff"}, "trust_signals": ["uptime and reliability stats", "security and SOC2 compliance badges", "API response time and performance metrics", "user and company count", "enterprise customer logos", "open source or transparent model info", "data privacy and no-training guarantees"], "ux_norms": ["keyboard-first interactions expected", "dark mode is the primary and default mode", "dense information layouts are acceptable — users are technical", "command palette (CMD+K) expected at scale", "code blocks and syntax highlighting required", "streaming output (typewriter effect) for AI responses", "token and usage counters always visible", "model and configuration selection prominent"], "icons": {"style": "geometric modern line", "weight": "light to medium", "mood": "technical, forward-thinking, precise", "library": {"name": "Lucide", "variant": "Rounded line", "url": "https://lucide.dev"}, "domain_icons": ["cpu", "brain", "zap", "sparkles", "terminal", "layers", "code", "git-branch", "activity", "shield", "globe", "network"], "nav_icons": ["home", "plus-circle", "clock", "bookmark", "user", "settings", "key", "layers", "arrow-left", "menu"]}, "visual_language": {"primary_type": "SVG vector illustrations and CSS", "style": "abstract geometric — neural network patterns, gradient meshes, data visualisation", "photography_rules": ["no photography on core product screens", "real team photos only on about/marketing pages", "never use generic tech stock photos (server rooms, handshakes)"], "background_treatment": "deep dark — near black with subtle gradient or