  ('travel_lifestyle', 'Travel & Lifestyle', ARRAY['Marketplace', 'Booking & Appointments', 'Map & Location-Based']::text[], '{"industry_id": "travel_lifestyle", "industry_name": "Travel & Lifestyle", "tone": {"primary": "adventurous, aspirational, liberating", "secondary": "trustworthy, helpful, culturally aware", "voice": "a well-travelled friend who has been everywhere and knows all the best spots — inspiring but practical", "avoid": "corporate, generic, overly cautious, tourist-trap feeling"}, "trust_signals": ["verified traveller reviews and ratings", "real guest or visitor photography", "booking confirmation and instant availability", "secure payment and refund policy", "host or operator verification badges", "response time and acceptance rate for hosts", "travel insurance integration"], "ux_norms": ["full-bleed destination photography dominates every screen", "map view is always an alternative to list view", "date picker and guest selector are primary UI elements", "save to wishlist is a primary action on every listing", "price transparency — total cost always shown before checkout", "itinerary view expected for multi-day bookings", "reviews and photos from real travellers drive decisions", "availability calendar always accessible on listing detail"], "icons": {"style": "rounded line, airy, light weight", "weight": "light", "mood": "adventurous, aspirational, open", "library": {"name": "Lucide", "variant": "Rounded line", "url": "https://lucide.dev"}, "domain_icons": ["plane", "map-pin", "compass", "mountain", "camera", "sun", "palm-tree", "luggage", "star", "globe", "bed", "navigation"], "nav_icons": ["home", "search", "heart", "calendar", "user", "bell", "map", "list", "arrow-left", "filter"]}, "visual_language": {"primary_type": "real photography", "style": "stunning destination photography — wide landscapes, golden hour, authentic local life", "photography_rules": ["always use high quality destination and lifestyle photography", "golden hour and natural l