INSERT INTO public.products (archetype_id, name, description, valid_industries, brain, sort_order) VALUES
  ('ai_core', 'AI Tool', 'AI-powered product where the AI is the core experience. Industry brain defines the domain the AI operates in. This core defines how AI interaction, generation, and configuration work.', ARRAY['AI & Technology']::text[], '{"archetype_id": "ai_core", "archetype_name": "AI Tool", "description": "AI-powered product where the AI is the core experience. Industry brain defines the domain the AI operates in. This core defines how AI interaction, generation, and configuration work.", "valid_industries": ["AI & Technology"], "icon_pack": {"default_library": {"name": "Lucide", "variant": "Rounded line", "url": "https://lucide.dev"}, "industry_overrides": {}, "core_nav_icons": ["home", "plus-circle", "clock", "bookmark", "user", "settings", "key", "layers", "arrow-back", "menu"], "core_domain_icons": ["cpu", "sparkles", "zap", "copy", "refresh-cw", "thumbs-up", "thumbs-down", "stop-circle", "send", "paperclip"]}, "landing_page": {"sections": [{"id": "hero", "generates_images": false}, {"id": "how_it_works", "generates_images": false}, {"id": "pricing", "generates_images": false}, {"id": "cta_footer", "generates_images": false}]}, "core_entities": {"entities": ["User", "Conversation", "Message", "Generation", "Prompt", "Model", "Usage", "APIKey", "Project", "Template", "Output", "Feedback"], "relationships": ["User owns many Conversations", "Conversation contains many Messages", "Message is either from User or from AI", "Generation is the AI output from a Message or Prompt", "Prompt is a saved input created by User", "Model is the AI model configuration — version, temperature, context length", "Usage tracks tokens consumed and cost per User or Organisation", "APIKey belongs to User or Organisation — grants programmatic access", "Project groups Conversations by topic or purpose", "Template is a reusable Prompt created by User", "Output is a saved Generation — image, text, code, or file", "Feedback belongs to Message — thumbs up or down plus optional note"]}, "tiers": {"mvp": {"tier": "MVP", "description": "Core AI interaction — chat with AI, get generations, view history.", "screen_count": 8, "primary_flows": ["Sign up → start new conversation → type prompt → receive AI generation → continue conversation", "View conversation history → open past conversation → continue from where left off", "View usage → check remaining credits"], "secondary_flows": ["Copy AI output", "Regenerate response", "Give feedback on response", "Share conversation link"], "screens": [{"id": "home", "name": "Home / New Chat", "purpose": "Start new conversation — prompt entry and quick start options", "visual": "Clean dark interface. Prompt input bar at centre or bottom. Quick start prompts. Model indicator.", "entities": ["Conversation", "Message", "Model"], "actions": ["Type prompt", "Start new conversation", "Select quick start prompt", "View recent conversations", "Select model"]}, {"id": "conversation", "name": "Conversation / Chat", "purpose": "Active AI conversation — messages, generations, and controls", "visual": "Message thread. User bubbles right. AI response left with avatar. Streaming text. Input bar.", "entities": ["Conversation", "Message", "Generation", "Feedback"], "actions": ["Send message", "Regenerate response", "Copy response", "Give thumbs up or down", "Attach file or image", "Stop generation", "Edit user message"]}, {"id": "history", "name": "Conversation History", "purpose": "All past conversations — search and resume", "visual": "Conversation list with title and date. Search bar. Delete option.", "entities": ["Conversation", "User"], "actions": ["Browse all conversations", "Search conversations", "Open conversation", "Delete conversation", "Rename conversation"]}, {"id": "saved_outputs", "name": "Saved Outputs", "purpose": "Outputs the user has saved for later use", "visual": "Output cards grid. Type indicator — text, code, image. Copy and share.", "entities": ["Output", "Generation"], "actions": ["View saved outputs",