  ('booking_core', 'Booking & Appointments', 'Service booking platform connecting users with providers. Industry brain defines what is being booked. This core defines how booking works.', ARRAY['Beauty & Wellness', 'Healthcare', 'Fitness & Sport', 'Travel & Lifestyle', 'Real Estate', 'Transport & Logistics', 'Events & Ticketing', 'Food & Beverage']::text[], '{"archetype_id": "booking_core", "archetype_name": "Booking & Appointments", "description": "Service booking platform connecting users with providers. Industry brain defines what is being booked. This core defines how booking works.", "valid_industries": ["Beauty & Wellness", "Healthcare", "Fitness & Sport", "Travel & Lifestyle", "Real Estate", "Transport & Logistics", "Events & Ticketing", "Food & Beverage"], "icon_pack": {"default_library": {"name": "Lucide", "variant": "Rounded line", "url": "https://lucide.dev"}, "industry_overrides": {"Beauty & Wellness": {"name": "Phosphor Icons", "variant": "Duotone", "url": "https://phosphoricons.com"}, "Healthcare": {"name": "Material Symbols", "variant": "Rounded", "url": "https://fonts.google.com/icons"}, "Fitness & Sport": {"name": "Tabler Icons", "variant": "Bold line", "url": "https://tabler.io/icons"}, "Real Estate": {"name": "Material Symbols", "variant": "Outlined", "url": "https://fonts.google.com/icons"}}, "core_nav_icons": ["home", "search", "calendar", "heart", "user", "bell", "clock", "list", "arrow-back", "check"], "core_domain_icons": ["calendar", "clock", "check-circle", "star", "user", "map-pin", "repeat", "bell", "plus", "x"]}, "landing_page": {"sections": [{"id": "hero", "generates_images": true}, {"id": "how_it_works", "generates_images": false}, {"id": "pricing", "generates_images": false}, {"id": "cta_footer", "generates_images": false}]}, "core_entities": {"entities": ["User", "Provider", "Service", "Availability", "Appointment", "Review", "Payment", "Notification", "Location", "WaitList", "Package", "Staff"], "relationships": ["Provider offers ma