t", "Raise dispute"]}], "interaction_patterns": ["All MVP and Startup interaction patterns", "Dynamic pricing badge on peak slots — price shown in amber or red", "Membership discount automatically applied at confirmation — highlighted in green", "Multi-location map clusters — tap to expand and select location", "Staff utilisation heat map — darker = busier — visual at a glance", "Corporate booking shows company budget remaining — progress bar", "Gift card design previews as user selects — live render", "Provider payout pending vs available clearly colour coded"]}}}'::jsonb, 2),
  ('chat_core', 'Chat / Messaging', 'Real-time communication platform. Industry brain defines the context and purpose of communication. This core defines how messaging, channels, and real-time interaction work.', ARRAY['Healthcare']::text[], '{"archetype_id": "chat_core", "archetype_name": "Chat / Messaging", "description": "Real-time communication platform. Industry brain defines the context and purpose of communication. This core defines how messaging, channels, and real-time interaction work.", "valid_industries": ["Healthcare"], "icon_pack": {"default_library": {"name": "Lucide", "variant": "Rounded line", "url": "https://lucide.dev"}, "industry_overrides": {"Healthcare": {"name": "Material Symbols", "variant": "Rounded", "url": "https://fonts.google.com/icons"}}, "core_nav_icons": ["home", "message-circle", "phone", "user", "bell", "settings", "search", "plus", "arrow-back", "dots"], "core_domain_icons": ["message-circle", "phone", "video", "mic", "mic-off", "camera-off", "paperclip", "smile", "send", "check-check"]}, "landing_page": {"sections": [{"id": "hero", "generates_images": false}, {"id": "security_section", "generates_images": false}, {"id": "pricing", "generates_images": false}, {"id": "cta_footer", "generates_images": false}]}, "core_entities": {"entities": ["User", "Conversation", "Message", "Channel", "Attachment", "Reaction", "Notification", "Contact", "Group", "Call", "Status", "Bot"], "relationships": ["User has many Conversations", "Conversation is between two or more Users", "Message belongs to Conversation, sent by User", "Channel is a group Conversation with a topic", "Attachment belongs to Message — file, image, video", "Reaction belongs to Message, sent by User", "Notification belongs to User, triggered by new Message or mention", "Contact is a User saved by another User", "Group is a named Conversation with many Users", "Call is initiated between Users, can be voice or video", "Status belongs to User — online, away, busy, offline", "Bot is a special User type that sends automated Messages"]}, "tiers": {"mvp": {"tier": "MVP", "description": "Core messaging — 1-1 chat, group chat, media sharing, notifications.", "screen_count": 8, "primary_flows": ["Sign up → set up profile → find contact → start conversation → send message → receive reply", "Create group → add members → send message to group → members reply", "Receive notification → open message → reply → continue conversation"], "secondary_flows": ["Share image or file", "Search messages", "Mute conversation", "Block contact"], "screens": [{"id": "conversations", "name": "Conversations / Inbox", "purpose": "All conversations — recent, unread, sorted by last activity", "visual": "Conversation list. Avatar. Name. Last message preview. Timestamp. Unread count badge.", "entities": ["Conversation", "Message", "User"], "actions": ["View all conversations", "Tap conversation to open", "Search conversations", "Start new conversation", "Mark as unread"]}, {"id": "chat", "name": "Chat / Message Thread", "purpose": "Full conversation thread with message input", "visual": "Message bubbles. Sender avatar. Timestamp. Media inline. Input bar at bottom.", "entities": ["Message", "Conversation", "User", "Attachment"], "actions": ["Send text message", "Send emoji", "Attach image or file", "Record voice message", "Long press message for options", "React to message", "Reply to message"]}, {"id": "new_conversation", "name": "New Conversation", "purpose": "Start a new 1-1 or group conversation", "visual": "Contact list. Search bar. Select multiple for group. Next CTA.", "entities": ["User", "Contact", "Conversation"], "actions": ["Search contacts", "Select contact for 1-1", "Select multiple for group", "Create conversation"]}, {"id": "group_info", "name": "Group Info", "purpose": "Group details — members, media, settings", "visual": "Group avatar. Name. Member list. Shared media grid. Settings.", "entities": ["Group", "User", "Attachment"], "actions": ["View members", "Add member", "View shared media", "Mute group", "Leave group", "Edit group name or avatar"]}, {"id": "contact_profile", "name": "Contact Profile", "purpose": "Contact details — status, shared media, actions", "visual": "Avatar. Status. Shared media. Action buttons — message, call.", "entities": ["User", "Contact", "Attachment"], "actions": ["Send message", "Start call", "View shared media", "Block contact", "Mute notifications"]}, {"id": "search", "name": "Search", "purpose": "Search messages, contacts, and conversations", "visual": "Search bar. Tabs — messages, contacts, files. Results list.", "entities": ["Message", "User", "Attachment"], "actions": ["Search messages", "Search contacts", "Search files", "Tap result to navigate"]}, {"id": "profile", "name": "Own Profile", "purpose": "Set own profile — avatar, name, status", "visual": "Avatar upload. Name. Status selector. Bio.", "entities": ["User"], "actions": ["Edit avatar", "Edit name", "Set status", "Edit bio"]}, {"id": "settings", "name": "Settings", "purpose": "App settings — notifications, privacy, account", "visual": "Settings list. Notification settings. Privacy. Storage. Account.", "entities": ["User"], "actions": ["Notification settings", "Privacy settings", "Storage management", "Account settings", "Log out"]}], "interaction_patterns": ["Message bubbles — sent messages right aligned, received left aligned", "Typing indicator — animated dots in conversation", "Read receipts — single tick sent, double tick delivered, filled double tick read", "Long press message — context menu with react, reply, copy, delete", "Swipe right on message to reply — quoted message appears in input", "Emoji reaction picker — long press or double tap to react", "Unread badge on conversation — bold conversation name", "Online status dot on avatar — green online, grey offline"]}, "startup": {"tier": "Startup", "description": "Full messaging app with voice and video calls, channels, file sharing, and reactions.", "screen_count": 14, "primary_flows": ["All MVP flows", "Start voice or video call → ring → recipient answers → talk → end call → view call history", "Join channel → browse messages → participate → receive channel notifications", "Share file → recipient previews → downloads file"], "secondary_flows": ["All MVP secondary flows", "Pin important message", "Forward message", "Set custom notification per conversation", "View contact''s status story", "Schedule message"], "screens": [{"id": "conversations", "name": "Conversations / Inbox", "purpose": "Full inbox with starred, archived, and call history tabs", "visual": "Tabs — chats, calls, channels. Starred conversations pinned. Unread count.", "entities": ["Conversation", "Message", "User", "Call"], "actions": ["All MVP actions", "View calls tab", "View channels tab", "Star conversation", "Archive conversation"]}, {"id": "chat", "name": "Chat / Message Thread", "purpose": "Rich chat with pinned messages, reactions, and scheduling", "visual": "Thread. Pinned message banner. Rich reactions. Reply thread. Schedule icon in input.", "entities": ["Message", "Conversation", "User", "Attachment"], "actions": ["All MVP actions", "Pin message", "React with emoji", "Open reply thread", "Schedule message", "Forward message"]}, {"id": "reply_thread", "name": "Reply Thread", "purpose": "Threaded replies on a specific message", "visual": "Original message at top. Thread replies below. Reply input.", "entities": ["Message", "User"], "actions": ["View thread replies", "Add reply to thread", "React in thread", "Navigate back to main chat"]}, {"id": "calls", "name": "Calls", "purpose": "Initiate and view call history", "visual": "Call history list. Incoming, outgoing, missed badges. Call back CTA.", "entities": ["Call", "User"], "actions": ["View call history", "Call back", "Start new voice call", "Start new video call", "Filter by missed"]}, {"id": "voice_video_call", "name": "Voice / Video Call", "purpose": "Active call screen with controls", "visual": "Fu