s", "visual": "Avatar. Status. Online time. Mutual groups. Media. Actions.", "entities": ["User", "Contact", "Attachment"], "actions": ["All MVP actions", "View mutual groups", "Video call"]}, {"id": "status", "name": "Status / Stories", "purpose": "24-hour status updates from contacts", "visual": "Status circles row. Full-screen status view. Reactions.", "entities": ["Status", "User"], "actions": ["View contact status", "React to status", "Post own status", "View who saw status"]}, {"id": "notifications", "name": "Notifications", "purpose": "All message, call, and channel notifications", "visual": "Notification list. Message preview. Call missed. Channel mention.", "entities": ["Notification", "Message", "Call"], "actions": ["View all", "Tap to navigate", "Mark read", "Manage per-conversation notifications"]}, {"id": "settings", "name": "Settings", "purpose": "Full settings with call quality, storage, and privacy", "visual": "Settings list. Call quality. Storage. Privacy. Notification. Account.", "entities": ["User"], "actions": ["All MVP actions", "Call quality settings", "Storage usage and clear", "Privacy — last seen, read receipts"]}], "interaction_patterns": ["All MVP interaction patterns", "Pinned message banner at top of chat — tap to jump to message", "Incoming call screen — full-screen overlay with accept and decline", "Video call — tap to show or hide controls", "Thread badge — shows reply count on message in main thread", "Channel mention @name — highlighted in accent colour", "Status ring on avatar — colour indicates status or story available", "Forward message — contact picker slides up"]}, "scale": {"tier": "Scale", "description": "Enterprise messaging platform with workspaces, bots, integrations, compliance, and admin.", "screen_count": 22, "primary_flows": ["All MVP and Startup flows", "Enterprise admin creates workspace → adds teams → sets permissions → members onboard via SSO", "Set up bot → configure commands → bot responds to triggers in channels", "Connect integration → app posts updates to channel automatically → team notified", "Compliance admin exports message history → satisfies audit requirement", "Group video call with 50+ participants — breakout rooms, screen share, recording"], "secondary_flows": ["All previous secondary flows", "Screen sharing in calls", "Call recording with consent", "Message retention policies", "Custom emoji and reactions", "Workflow automation from messages"], "screens": [{"id": "conversations", "name": "Conversations / Inbox", "purpose": "Workspace-aware inbox with team channels and DMs", "visual": "Workspace sidebar. Channels section. DMs section. Threads. Activity.", "entities": ["Conversation", "Message", "User", "Call", "Channel"], "actions": ["All Startup actions", "Switch workspace", "View activity feed", "View threads view"]}, {"id": "chat", "name": "Chat / Message Thread", "purpose": "Rich enterprise chat with workflow triggers and bookmarks", "visual": "Thread. Bookmark icon. Workflow trigger from message. Slash commands.", "entities": ["Message", "Conversation", "User", "Attachment"], "actions": ["All Startup actions", "Bookmark message", "Trigger workflow from message", "Use slash commands"]}, {"id": "reply_thread", "name": "Reply Thread", "purpose": "Threaded discussion with follow thread option", "visual": "Original message. Replies. Follow thread toggle. Reply input.", "entities": ["Message", "User"], "actions": ["All Startup actions", "Follow thread — get notifications"]}, {"id": "calls", "name": "Calls & Meetings", "purpose": "Full call history with scheduled meetings", "visual": "Call history. Scheduled meetings section. Join meeting CTA.", "entities": ["Call", "User"], "actions": ["All Startup actions", "View scheduled meetings", "Join upcoming meeting"]}, {"id": "voice_video_call", "name": "Voice / Video Call / Meeting", "purpose": "Enterprise meeting with screen share, recording, breakout rooms", "visual": "Grid view of participants. Controls — mute, came