workflows", "visual": "Integration cards. Connected status. Channel assignment. Configure.", "entities": ["Channel", "Organisation"], "actions": ["Browse integrations", "Connect integration", "Assign to channel", "Configure triggers", "Disconnect"]}, {"id": "automations", "name": "Workflow Automations", "purpose": "Set trigger-action automations from messages or events", "visual": "Workflow list. Builder. Trigger selector. Action chain.", "entities": ["Message", "Channel", "User"], "actions": ["Create workflow", "Set message trigger", "Add actions", "Test workflow", "Enable or disable"]}, {"id": "admin_workspace", "name": "Admin — Workspace Settings", "purpose": "Workspace configuration — SSO, permissions, retention", "visual": "Admin sidebar. General. Members. Permissions. Retention. Security.", "entities": ["Organisation", "User"], "actions": ["Configure SSO", "Set member permissions", "Set message retention policy", "View workspace usage stats"]}, {"id": "admin_members", "name": "Admin — Member Management", "purpose": "Manage all workspace members and roles", "visual": "Member table. Role badge. Deactivate CTA. Guest member indicator.", "entities": ["User", "Organisation"], "actions": ["View all members", "Change role", "Deactivate member", "Invite member", "Manage guest access"]}, {"id": "compliance_export", "name": "Compliance & Export", "purpose": "Export message history for audit and compliance", "visual": "Export form. Date range. Channel selector. Format selector. Download.", "entities": ["Message", "Organisation"], "actions": ["Select date range", "Select channels", "Select export format", "Start export", "Download export"]}, {"id": "analytics_admin", "name": "Admin — Analytics", "purpose": "Workspace usage — active users, messages, channels, calls", "visual": "DAU chart. Message volume. Channel activity. Call usage. Export.", "entities": ["User", "Message", "Channel"], "actions": ["View DAU", "View message volume", "View channel activity", "View call usage", "Export report"]}, {"id": "search", "name": "Search", "purpose": "Enterprise-wide search across all channels and files", "visual": "Search bar. Filters — from, in, date. Results with context.", "entities": ["Message", "User", "Attachment"], "actions": ["All Startup actions", "Filter by sender", "Filter by channel", "Filter by date range", "Search in files"]}, {"id": "activity", "name": "Activity Feed", "purpose": "All mentions, replies, and reactions directed at the user", "visual": "Activity list. Mentions tab. Threads tab. Reactions tab.", "entities": ["Notification", "Message", "User"], "actions": ["View all activity", "Filter by type", "Mark all read", "Navigate to message"]}, {"id": "bookmarks", "name": "Bookmarks", "purpose": "Saved messages and files across all conversations", "visual": "Bookmarks list. Conversation source. Jump to message.", "entities": ["Message", "User"], "actions": ["View all bookmarks", "Jump to message", "Remove bookmark", "Organise by folder"]}, {"id": "notifications", "name": "Notifications", "purpose": "Priority notifications with do not disturb schedule", "visual": "Notification list. DND schedule. Priority senders. Per-channel settings.", "entities": ["Notification", "Message", "Call"], "actions": ["All Startup actions", "Set DND schedule", "Add priority senders", "Per-channel notification settings"]}, {"id": "profile", "name": "Own Profile", "purpose": "Enterprise profile with status, timezone, and pronouns", "visual": "Avatar. Status with expiry. Timezone. Pronouns. Contact info.", "entities": ["User"], "actions": ["Set custom status with expiry", "Set timezone", "Add pronouns", "Edit contact info"]}, {"id": "settings", "name": "Settings", "purpose": "Enterprise settings with accessibility, theme, and security", "visual": "Full settings sidebar. Theme. Accessibility. Two-factor. Devices. Privacy.", "entities": ["User"], "actions": ["All Startup actions", "Theme settings", "Accessibility settings", "Manage trusted devices", "Two-factor settings"]}], "interaction_patterns": ["All MVP and Startup interaction patterns", "Slash command autocomplete — / triggers command list in input", "Breakout room assignment — drag and drop members into rooms", "Screen share request — permission overlay on recipient screen", "Meeting transcription indicator — live text scrolls during call", "Integration post — distinct visual style in channel — app icon + formatted message", "Retention policy banner on channel — messages delete after X days indicator", "Workflow trigger button on message — action button below message", "Custom status — emoji + text + expiry time — shows next to name everywhere"]}}}'::jsonb, 3),
  ('dashboard_core', 'Dashboard SaaS', 'B2B or B2C SaaS with a data dashboard at its core. Industry brain defines the domain. This core defines how the SaaS product is structured and experienced.', ARRAY['Healthcare', 'Finance', 'Real Estate', 'Transport & Logistics', 'Education', 'AI & Technology', 'Developer Tools']::text[], '{"archetype_id": "dashboard_core", "archetype_name": "Dashboard SaaS", "description": "B2B or B2C SaaS with a data dashboard at its core. Industry brain defines the domain. This core defines how the SaaS product is structured and experienced.", "valid_industries": ["Healthcare", "Finance", "Real Estate", "Transport & Logistics", "Education", "AI & Technology", "Developer Tools"], "icon_pack": {"default_library": {"name": "Material Symbols", "variant": "Outlined", "url": "https://fonts.google.com/icons"}, "industry_overrides": {"Finance": {"name": "Material Symbols", "variant": "Sharp", "url": "https://fonts.google.com/icons"}, "Healthcare": {"name": "Material Symbols", "variant": "Rounded", "url": "https://fonts.google.com/icons"}, "Transport & Logistics": {"name": "Material Symbols", "variant": "Sharp", "url": "https://fonts.google.com/icons"}, "Developer Tools": {"name": "Material Symbols", "variant": "Sharp", "url": "https://fonts.google.com/icons"}}, "core_nav_icons": ["home", "bar_chart", "group", "description", "person", "notifications", "settings", "arrow_back", "menu", "refresh"], "core_domain_icons": ["bar_chart", "trending_up", "pie_chart", "table_chart", "filter_list", "download", "upload", "search", "tune", "more_vert"]}, "landing_page": {"sections": [{"id": "hero", "generates_images": false}, {"id": "stats_bar", "generates_images": false}, {"id": "pricing", "generates_images": false}, {"id": "cta_footer", "generates_images": false}]}, "core_entities": {"entities": ["User", "Organisation", "Project", "Record", "Report", "Metric", "Notification", "Integration", "Team", "Role", "AuditLog", "Subscription"], "relationships": ["Organisation has many Users with Roles", "User belongs to Organisation with a Role (admin, member, viewer)", "Project belongs to Organisation, contains Records", "Record is the core data unit — its definition varies by industry (patient, property, loan, shipment, etc.)", "Report is generated from Records and Metrics", "Metric is a computed value from Records", "Integration connects the Organisation to external services", "Team is a subset of Users within an Organisation", "AuditLog records all actions by Users", "Subscription defines the plan and feature access for an Organisation", "Notification belongs to User, triggered by system events or thresholds"]}, "tiers": {"mvp": {"tier": "MVP", "description": "Core SaaS — login, dashboard overview, record management, basic reporting.", "screen_count": 8, "primary_flows": ["Sign up → create organisation → invite team → set up project → add records → view dashboard", "Log in → view dashboard → browse records → view record detail → take action", "View dashboard metrics → identify issue → navigate to relevant records"], "secondary_flows": ["Export data as CSV", "Search and filter records", "Edit record", "View basic report"], "screens": [{"id": "login", "name": "Login", "purpose": "Secure authentication", "visual": "Dark or clean light. Logo. Email and password. SSO option.", "entities": ["User", "Organisation"], "actions": ["Email login", "SSO login", "Forgot password", "Sign up"]}, {"id": "onboarding", "name": "Onboarding", "purpose": "Organisation and project setup", "visual": "Step flow. Progress bar. Form inputs. Invite team step.", "entities": ["User", "Organisation", "Project", "Team"], "actions": ["Set organisation name", "Set up first project", "Invite team members", "Complete setup"]}, {"id": "dashboard", "name": "Dashboard / Overview", "purpose": "Key metrics at a glance — the command centre", "visual": "KPI cards at top. Charts below. Recent activity list. Quick action buttons.", "entities": ["Metric", "Record", "Notification"], "actions": ["View KPIs", "View charts", "View recent activity", "Quick navigate to records", "View notifications"]}, {"id": "records_list", "name": "Records List", "purpose": "Browse, search, and filter all records", "visual": "Data table. Search bar. Filter controls. Sort. Row click to detail.", "entities": ["Record", "Project"], "actions": ["Search records", "Filter by status, date, or type", "Sort columns", "Click row for detail", "Create new record", "Export CSV"]}, {"id": "record_detail", "name": "Record Detail", "purpose": "Full record view with all fields and action history", "visual": "Record header. Field sections. Activity timeline on right or below.", "entities": ["Record", "User"], "actions": ["View all fields", "Edit record", "View activity timeline", "Change status", "Delete record", "Add note or comment"]}, {"id": "create_edit_record", "name": "Create / Edit Record", "purpose": "Form to create or edit a record", "visual": "Clean form. Grouped fields. Validation indicators. Save and cancel.", "entities": ["Record"], "actions": ["Fill fields", "Validate inputs", "Save record", "Cancel", "Duplicate record"]}, {"id": "reports", "name": "Reports", "purpose": "Basic pre-built reports from record data", "visual": "Report cards. Chart visualisations. Date range picker. Export CTA.", "entities": ["Report", "Metric", "Record"], "actions": ["View report", "Change date range", "Export PDF or CSV", "Filter report data"]}, {"id": "settings", "name": "Settings", "purpose": "Account and organisation settings", "visual": "Settings sidebar. Profile section. Organisation section.", "entities": ["User", "Organisation"], "actions": ["Edit profile", "Change password", "Organisation settings", "Notification preferences", "Log out"]}], "interaction_patterns": ["KPI cards animate in on dashboard load — counter counts up to value", "Table row hover highlights — click to open detail", "Filter panel slides in from right or drops down inline", "Record status badge — colour coded by status", "Form validation inline — red border and message on error", "Empty state on records list — clear CTA to create first record", "Toast notification on save or action success"]}, "startup": {"tier": "Startup", "description": "Full SaaS with team management, notifications, integrations, advanced reporting, and role-based access.", "screen_count": 15, "primary_flows": ["All MVP flows", "Admin invites team member → assigns role → member logs in → sees role-based view", "Connect integration → authenticate external service → data syncs → appears in dashboard", "Set metric threshold → trigger fires → notification sent → user investigates", "Build custom report → select metrics → visualise → share with team"], "secondary_flows": ["All MVP secondary flows", "Export report as PDF", "Comment and tag teammate on record", "Set up recurring report email", "View audit log", "Archive record"], "screens": [{"id": "login", "name": "Login", "purpose": "Secure auth with MFA", "visual": "Clean. Logo. Email, password, MFA step.", "entities": ["User", "Organisation"], "actions": ["Login", "MFA", "SSO", "Forgot password"]}, {"id": "onboarding", "name": "Onboarding", "purpose": "Full org setup with integrations step", "visual": "Steps. Org setup. Project. Team invite. Integration connect. Done.", "entities": ["User", "Organisation", "Project", "Team", "Integration"], "actions": ["All MVP actions", "Connect integration during onboarding"]}, {"id": "dashboard", "name": "Dashboard / Overview", "purpose": "Role-based dashboard with custom metric widgets", "visual": "KPI cards. Customisable widget grid. Alerts panel. Recent activity.", "entities": ["Metric", "Record", "Notification"], "actions": ["All MVP actions", "Customise widget layout", "View threshold alerts", "Filter by team or project"]}, {"id": "records_list", "name": "Records List", "purpose": "Full record management with bulk actions and views", "visual": "Data table. List or Kanban view toggle. Bulk select. Filter. Sort.", "entities": ["Record", "Project"], "actions": ["All MVP actions", "Toggle list or Kanban", "Bulk select and action", "Save filter as view", "Assign records to team"]}, {"id": "record_detail", "name": "Record Detail", "purpose": "Full record with comments, mentions, and file attachments", "visual": "Record fields. Comment thread with mentions. File attachments. Activity log.", "entities": ["Record", "User"], "actions": ["All MVP actions", "Comment with mention", "Attach file", "View full activity log", "Assign to team member"]}, {"id": "create_edit_record", "name": "Create / Edit Record", "purpose": "Rich form with file upload and linked records", "visual": "Grouped form. File upload. Link to related record. Validation.", "entities": ["Record"], "actions": ["All MVP actions", "Upload file", "Link to related record"]}, {"id": "reports", "name": "Reports", "purpose": "Custom report builder with saved and shared reports", "visual": "Report builder sidebar. Chart preview. Save and share. Report library.", "entities": ["Report", "Metric", "Record"], "actions": ["All MVP actions", "Build custom report", "Select chart type", "Save report", "Share report with team", "Schedule email report"]}, {"id": "analytics", "name": "Analytics", "purpose": "Deeper analytics — trends, comparisons, cohorts", "visual": "Trend line charts. Comparison view. Period selector. Export.", "entities": ["Metric", "Record"], "actions": ["View trend over time", "Compare periods", "View cohort breakdown", "Export chart"]}, {"id": "team_management", "name": "Team Management", "purpose": "Invite, manage, and assign roles to team members", "visual": "Team member table. Role badge per member. Invite CTA. Pending invites.", "entities": ["User", "Team", "Role", "Organisation"], "actions": ["Invite member", "Assign role", "Remove member", "View pending invites", "Resend invite"]}, {"id": "integrations", "name": "Integrations", "purpose": "Connect external services — CRM, payment, calendar, etc.", "visual": "Integration cards grid. Connected status badge. Connect and disconnect.", "entities": ["Integration", "Organisation"], "actions": ["Browse integrations", "Connect integration", "Configure integration", "Disconnect", "View sync status"]}, {"id": "notifications", "name": "Notifications", "purpose": "All system alerts, threshold triggers, and team activity", "visual": "Notification list. Alert category. Threshold alert with value. Mark read.", "entities": ["Notification", "Record", "Metric"], "actions": ["View all", "Filter by type", "Mark read", "Navigate to relevant record"]}, {"id": "notification_settings", "name": "Notification Settings", "purpose": "Configure what triggers notifications and how they are delivered", "visual": "Trigger list. Toggle per trigger. Channel selector (email, in-app, Slack).", "entities": ["Notification", "User"], "actions": ["Toggle notification types", "Select delivery channel", "Set threshold values", "Test notification"]}, {"id": "audit_log", "name": "Audit Log", "purpose": "Full log of all user actions in the organisation", "visual": "Log table. User, action, timestamp, record. Filter and search.", "entities": ["AuditLog", "User", "Record"], "actions": ["View log", "Filter by user or action", "Search log", "Export log"]}, {"id": "settings", "name": "Settings", "purpose": "Full org and account settings", "visual": "Settings sidebar. Profile. Organisation. Team. Billing. Integrations. Security.", "entities": ["User", "Organisation", "Subscription"], "actions": ["All MVP actions", "Manage billing", "Security settings", "SSO configuration", "Data export"]}, {"id": "billing", "name": "Billing & Subscription", "purpose": "Plan management and billing history", "visual": "Current plan card. Feature comparison. Upgrade CTA. Invoice history.", "entities": ["Subscription", "Organisation"], "actions": ["View current plan", "Upgrade or downgrade", "View invoices", "Update payment method", "Cancel subscription"]}], "interaction_patterns": ["All MVP interaction patterns", "Widget drag and drop on dashboard — save layout", "Kanban card drag between status columns", "Mention autocomplete in comments — @ triggers user list", "Integration status pill — connected green, error red, syncing spinner", "Threshold alert banner on dashboard when metric fires", "Audit log row expands to full action detail on click", "Role badge on team member — colour coded by role level"]}, "scale": {"tier": "Scale", "description": "Enterprise SaaS with SSO, advanced permissions, multi-workspace, API, white-label, and compliance tools.", "screen_count": 24, "primary_flows": ["All MVP and Startup flows", "Enterprise admin sets up SSO → team logs in with company credentials → roles synced automatically", "Create custom workflow → set triggers and actions → automate record updates → view automation log", "Multi-workspace admin → switch between workspaces → manage each independently", "API consumer generates key → calls API → views usage dashboard → manages rate limits", "Compliance admin runs data audit → exports compliance report → satisfies regulatory requirement"], "secondary_flows": ["All previous secondary flows", "White-label custom domain and branding", "Data residency selection", "Custom field creation", "Webhook management", "Embedded dashboard for external sharing"], "screens": [{"id": "login", "name": "Login", "purpose": "Enterprise auth with SSO and device management", "visual": "Clean. SSO primary CTA. Email fallback. Device trust indicator.", "entities": ["User", "Organisation"], "actions": ["SSO login", "Email login", "MFA", "Trusted device"]}, {"id": "onboarding", "name": "Onboarding", "purpose": "Enterprise setup with SSO, data import, and workspace config", "visual": "Enterprise steps. SSO setup. Data import. Workspace config. Team sync.", "entities": ["User", "Organisation", "Project", "Team", "Integration"], "actions": ["All Startup actions", "Configure SSO", "Import data", "Sync team from directory"]}, {"id": "dashboard", "name": "Dashboard / Overview", "purpose": "Multi-workspace dashboard with executive summary view", "visual": "Workspace switcher. Executive KPIs. Alert panel. Widget grid. Embed toggle.", "entities": ["Metric", "Record", "Notification"], "actions": ["All Startup actions", "Switch workspace", "Toggle executive view", "Embed dashboard"]}, {"id": "records_list", "name": "Records List", "purpose": "Full record management with custom views and permissions", "visual": "Data table. Saved views tabs. Custom fields. Permission indicators.", "entities": ["Record", "Project"], "actions": ["All Startup actions", "Create custom view", "Manage custom fields", "View permission indicators"]}, {"id": "record_detail", "name": "Record Detail", "purpose": "Full record with workflow history and linked records graph", "visual": "Fields. Comments. Workflow history. Linked records graph. Full audit.", "entities": ["Record", "User"], "actions": ["All Startup actions", "View workflow history", "View linked records graph", "Export record"]}, {"id": "create_edit_record", "name": "Create / Edit Record", "purpose": "Rich form with conditional fields and workflow trigger", "visual": "Conditional field logic. Workflow trigger toggle. File upload. Linked records.", "entities": ["Record"], "actions": ["All Startup actions", "Conditional fields", "Trigger workflow on save"]}, {"id": "reports", "name": "Reports", "purpose": "Advanced reports with embedded sharing and scheduled delivery", "visual": "Report builder. Embed code. Schedule delivery. Public share link.", "entities": ["Report", "Metric", "Record"], "actions": ["All Startup actions", "Generate embed code", "Public share link", "Advanced schedule"]}, {"id": "analytics", "name": "Analytics", "purpose": "Executive analytics with forecasting and benchmarks", "visual": "Forecast line. Benchmark comparison. Cohort matrix. Full export.", "entities": ["Metric", "Record"], "actions": ["All Startup actions", "View forecast", "Compare to benchmark", "View cohort matrix"]}, {"id": "automations", "name": "Automations / Workflows", "purpose": "Build trigger-action automations for record management", "visual": "Automation builder canvas. Trigger selector. Action chain. Test and publish.", "entities": ["Record", "User", "Organisation"], "actions": ["Create automation", "Set trigger", "Add actions", "Add conditions", "Test automation", "View automation log"]}, {"id": "team_management", "name": "Team Management", "purpose": "Multi-team org with directory sync and granular permissions", "visual": "Team hierarchy. Directory sync status. Permission matrix. Invite.", "entities": ["User", "Team", "Role", "Organisation"], "actions": ["All Startup actions", "Sync from directory", "Set granular permissions", "View permission matrix", "Manage teams within org"]}, {"id": "workspaces", "name": "Multi-Workspace Management", "purpose": "Create and switch between separate workspaces", "visual": "Workspace cards. Create workspace. Switch. Settings per workspace.", "entities": ["Organisation"], "actions": ["View all workspaces", "Create workspace", "Switch workspace", "Configure workspace", "Archive workspace"]}, {"id": "integrations", "name": "Integrations", "purpose": "Enterprise integrations with webhook management and API", "visual": "Integration grid. Webhook list. API usage. Connected apps.", "entities": ["Integration", "Organisation"], "actions": ["All Startup actions", "Manage webhooks", "View API usage", "Configure enterprise integrations"]}, {"id": "api_access", "name": "API Access", "purpose": "API key management and developer documentation", "visual": "API key list. Usage chart. Rate limit indicator. Docs link.", "entities": ["Organisation", "User"], "actions": ["Generate API key", "View usage", "Set rate limits", "View documentation", "Revoke key"]}, {"id": "notifications", "name": "Notifications", "purpose": "All alerts with team digest and executive summary", "visual": "All notifications. Team digest. Executive summary option.", "entities": ["Notification", "Record", "Metric"], "actions": ["All Startup actions", "View team digest", "View executive summary"]}, {"id": "notification_settings", "name": "Notification Settings", "purpose": "Advanced notification routing with team digest and digest schedule", "visual": "Trigger matrix. Team digest schedule. Escalation rules.", "entities": ["Notification", "User"], "actions": ["All Startup actions", "Set escalation rules", "Configure digest schedule"]}, {"id": "audit_log", "name": "Audit Log", "purpose": "Full compliance audit log with data export for regulators", "visual": "Comprehensive log. Compliance export. Retention policy indicator.", "entities": ["AuditLog", "User", "Record"], "actions": ["All Startup actions", "Export compliance report", "Set retention policy"]}, {"id": "compliance", "name": "Compliance Centre", "purpose": "GDPR, SOC2, and other compliance management", "visual": "Compliance status cards. Data subject requests. Retention policies. Audit reports.", "entities": ["Organisation", "User"], "actions": ["View compliance status", "Process data subject request", "Set retention policies", "Download compliance report", "View certifications"]}, {"id": "white_label", "name": "White-Label Settings", "purpose": "Custom branding, domain, and email configuration", "visual": "Brand settings. Logo upload. Colour picker. Custom domain. Email templates.", "entities": ["Organisation"], "actions": ["Upload logo", "Set brand colours", "Configure custom domain", "Set email templates", "Preview white-label"]}, {"id": "settings", "name": "Settings", "purpose": "Enterprise settings hub", "visual": "Settings sidebar. All sections. Compliance. White-label. SSO. Data.", "entities": ["User", "Organisation", "Subscription"], "actions": ["All Startup actions", "SSO configuration", "White-label settings", "Compliance settings", "Data residency"]}, {"id": "billing", "name": "Billing & Subscription", "purpose": "Enterprise billing with usage-based and contract support", "visual": "Enterprise plan card. Usage meters. Contract info. Invoice history.", "entities": ["Subscription", "Organisation"], "actions": ["View enterprise plan", "View usage meters", "Download invoices", "Contact sales for contract"]}, {"id": "admin_dashboard", "name": "Super Admin Dashboard", "purpose": "Platform-level admin — all orgs, revenue, health", "visual": "Org table. Revenue chart. Health indicators. Support queue.", "entities": ["Organisation", "User"], "actions": ["View all orgs", "View platform revenue", "View health metrics", "Access org as admin", "View support queue"]}, {"id": "custom_fields", "name": "Custom Fields", "purpose": "Define custom fields for records across the organisation", "visual": "Field type selector. Preview. Assign to record type. Required toggle.", "entities": ["Record", "Organisation"], "actions": ["Create custom field", "Select field type", "Assign to record type", "Set required", "Reorder fields", "Delete field"]}, {"id": "help_centre", "name": "Help Centre", "purpose": "Self-serve help with admin and developer sections", "visual": "Search. User, admin, and developer categories. API docs link.", "entities": ["User"], "actions": ["Search", "Browse categories", "Developer docs", "Contact enterprise support"]}, {"id": "embedded_dashboard", "name": "Embedded Dashboard", "purpose": "Share read-only dashboard externally without login", "visual": "Clean dashboard view. No nav. Powered by badge. Embed code.", "entities": ["Metric", "Report"], "actions": ["View embedded dashboard", "Filter if allowed", "Export if allowed"]}], "interaction_patterns": ["All MVP and Startup interaction patterns", "Workspace switcher — dropdown from top nav, switches context instantly", "Automation builder — drag nodes on canvas, connect with arrows", "Permission matrix — checkbox grid, rows are features, columns are roles", "API usage bar — fills as quota approaches, turns amber then red", "Compliance status card — green tick, amber warning, red alert", "White-label preview — live render updates as user changes brand settings", "Custom field drag to reorder — handle on left of field row", "Directory sync status — last synced time, manual sync button"]}}}'::jsonb, 4),
  ('dev_core', 'Developer Tool', 'Tool built for developers — code, APIs, CLIs, and technical workflows. Industry brain defines the development domain. This core defines how developer-first products are experienced.', ARRAY['Developer Tools', 'AI & Technology']::text[], '{"archetype_id": "dev_core", "archetype_name": "Developer Tool", "description": "Tool built for developers — code, APIs, CLIs, and technical workflows. Industry brain defines the development domain. This core defines how developer-first products are experienced.", "valid_industries": ["Developer Tools", "AI & Technology"], "icon_pack": {"default_library": {"name": "Tabler Icons", "variant": "Sharp line", "url": "https://tabler.io/icons"}, "industry_overrides": {"AI & Technology": {"name": "Material Symbols", "variant": "Outlined", "url": "https://fonts.google.com/icons"}}, "core_nav_icons": ["home", "code", "git-branch", "terminal", "users", "bell", "settings", "key", "arrow-back", "menu"], "core_domain_icons": ["terminal", "code", "git-branch", "key", "shield", "package", "rocket", "bug", "activity", "download"]}, "landing_page": {"sections": [{"id": "hero", "generates_images": false}, {"id": "code_example", "generates_images": false}, {"id": "pricing", "generates_images": false}, {"id": "cta_footer", "generates_images": false}]}, "core_entities": {"entities": ["User", "Project", "Repository", "File", "Build", "Deployment", "APIKey", "Log", "Environment", "Team", "Integration", "Usage", "Webhook", "Documentation"], "relationships": ["User belongs to a Team and owns or contributes to Projects", "Project contains Repositories and Environments", "Repository contains Files and has Builds", "Build belongs to Repository, has a Status and Logs", "Deployment belongs to Build, targets an Environment", "APIKey belongs to User or Project — grants API access", "Log belongs to Build or Deployment", "Environment belongs to Project — production, staging, development", "Integration connects Project to an external service", "Usage tracks API calls, compute, or storage per Project", "Webhook belongs to Project, fires on events", "Documentation is associated with Project or API"]}, "tiers": {"mvp": {"tier": "MVP", "description": "Core developer tool — project setup, API access, logs, basic deployment.", "screen_count": 8, "primary_flows": ["Sign up → create project → get API key → integrate → view usage", "Deploy project → monitor build → view logs → check deployment status", "Browse documentation → copy code snippet → integrate in own project"], "secondary_flows": ["View build history", "Download logs", "Invite team member", "Set environment variable"], "screens": [{"id": "dashboard", "name": "Dashboard / Projects", "purpose": "All projects — status, recent builds, quick actions", "visual": "Dark IDE aesthetic. Project cards with build status. Usage summary. Create project CTA.", "entities": ["Project", "Build", "Usage"], "actions": ["View all projects", "Create new project", "View build status", "View usage summary", "Quick navigate to project"]}, {"id": "project_detail", "name": "Project Detail", "purpose": "Single project overview — builds, deployments, usage, settings", "visual": "Project header with status badge. Tabs — overview, builds, logs, settings. Metrics cards.", "entities": ["Project", "Build", "Deployment", "Usage"], "actions": ["View overview", "View builds", "View logs", "Trigger deploy", "View usage", "Open settings"]}, {"id": "build_detail", "name": "Build / Deployment Detail", "purpose": "Build status, logs, and deployment info", "visual": "Build status header. Real-time log stream. Step progress. Error highlights.", "entities": ["Build", "Log", "Deployment"], "actions": ["View build status", "Stream logs", "View build steps", "View error detail", "Redeploy", "Cancel build"]}, {"id": "logs", "name": "Logs", "purpose": "Real-time and historical logs", "visual": "Terminal-style log viewer. Dark background. Monospace font. Filter bar. Search. Download.", "entities": ["Log", "Project", "Build"], "actions": ["Stream live logs", "Search logs", "Filter by severity", "Filter by time range", "Download logs", "Clear logs"]}, {"id": "api_keys", "name": "API Keys", "purpose": "Generate and manage API keys", "visual": "Key list. Masked by default. Reveal and copy. Created date. Last used. Delete.", "entities": ["APIKey", "User", "Project"], "actions": ["Generate new key", "Copy key", "Reveal key", "View last used", "Set key permissions", "Delete key"]}, {"id": "documentation", "name": "Documentation", "purpose": "API reference and integration guides", "visual": "Docs sidebar. Content area. Code examples with syntax highlighting. Copy snippets.", "entities": ["Documentation"], "actions": ["Browse docs", "Search docs", "View API reference", "Copy code snippet", "Select language for code example"]}, {"id": "usage", "name": "Usage & Billing", "purpose": "Usage metrics and billing", "visual": "Usage chart. Breakdown by type. Current period. Billing info. Plan indicator.", "entities": ["Usage", "Project"], "actions": ["View usage chart", "View breakdown", "View current period", "Update billing info", "View invoices"]}, {"id": "settings", "name": "Settings", "purpose": "Account and project settings", "visual": "Settings sidebar. Profile. Security. Notifications. Log out.", "entities": ["User", "Project"], "actions": ["Edit profile", "Security settings", "Notification preferences", "Delete account", "Log out"]}], "interaction_patterns": ["Build status badge — building spinner, success green, failed red", "Log stream — monospace font, auto-scroll, new lines append at bottom", "Error lines in logs — red background highlight", "API key masked — dots until reveal button tapped — copy after reveal", "Code examples — language tabs (JS, Python, curl) — switch without reload", "Copy code button — top right of every code block — changes to tick on copy", "Deploy button — triggers build — shows building state immediately", "Empty state — terminal-st