  ('ecommerce_core', 'E-commerce', 'Direct-to-consumer product selling platform. Industry brain defines what is sold and the visual world. This core defines how the shopping experience works.', ARRAY['Retail & Fashion', 'Beauty & Wellness', 'Food & Beverage']::text[], '{"archetype_id": "ecommerce_core", "archetype_name": "E-commerce", "description": "Direct-to-consumer product selling platform. Industry brain defines what is sold and the visual world. This core defines how the shopping experience works.", "valid_industries": ["Retail & Fashion", "Beauty & Wellness", "Food & Beverage"], "icon_pack": {"default_library": {"name": "Lucide", "variant": "Rounded line", "url": "https://lucide.dev"}, "industry_overrides": {"Retail & Fashion": {"name": "Remix Icons", "variant": "Ultra-thin line", "url": "https://remixicon.com"}, "Beauty & Wellness": {"name": "Phosphor Icons", "variant": "Duotone", "url": "https://phosphoricons.com"}}, "core_nav_icons": ["home", "search", "shopping-bag", "heart", "user", "bell", "filter", "grid", "arrow-back", "tag"], "core_domain_icons": ["shopping-cart", "heart", "star", "package", "truck", "tag", "percent", "gift", "return", "shield"]}, "landing_page": {"sections": [{"id": "hero", "generates_images": true}, {"id": "category_entry", "generates_images": true}, {"id": "featured_products", "generates_images": true}, {"id": "cta_footer", "generates_images": false}]}, "core_entities": {"entities": ["User", "Product", "Variant", "Category", "Cart", "Order", "Review", "Wishlist", "Payment", "Address", "Promotion", "Notification", "Return"], "relationships": ["Product belongs to one or more Categories", "Product has many Variants (size, colour, etc.)", "Cart belongs to User, contains Product Variants", "Order is created from Cart, belongs to User", "Order has a Payment and an Address", "Order has a Status (pending, confirmed, shipped, delivered, returned)", "Review belongs to User, written about a Product after Order", "Wishlist belongs to User, co