  ('finance_dashboard', 'Finance Dashboard', 'Finance-specific instantiation of the Dashboard SaaS archetype. Combines dashboard_core structure with finance industry context — personal finance, wealth management, banking, or fintech SaaS.', ARRAY[]::text[], '{"archetype_id": "dashboard_core", "industry_id": "finance", "file_id": "finance_dashboard", "description": "Finance-specific instantiation of the Dashboard SaaS archetype. Combines dashboard_core structure with finance industry context — personal finance, wealth management, banking, or fintech SaaS.", "industry_overrides": {"tone": "authoritative, precise, trustworthy — never casual with money", "trust_signals": ["bank-level encryption indicators", "regulatory compliance badges — FCA, SEC, FDIC", "two-factor authentication always visible", "transaction verification confirmation steps", "audit trail for all financial actions"], "visual_language": {"primary_type": "pure CSS + data visualisation", "style": "clean, data-dense, precise — numbers are the hero", "photography_rules": ["no photography — pure CSS and data viz only"], "background_treatment": "dark or neutral — high contrast for financial data legibility", "empty_state_style": "clean CSS illustration with prompt to connect accounts or add data", "chart_style": "line charts for trends, bar for comparisons, donut for allocation — always labelled"}, "record_type": "Transaction", "record_fields": ["amount", "currency", "date", "category", "merchant", "account", "status (pending, cleared, failed)", "reference", "notes", "tags"]}, "core_entities": {"entities": ["User", "Account", "Transaction", "Budget", "Goal", "Report", "Metric", "Portfolio", "Alert", "Integration", "Organisation", "Team", "Role", "AuditLog", "Subscription"], "relationships": ["User owns or belongs to an Organisation", "Account belongs to User or Organisation — bank, credit, investment, crypto", "Transaction belongs to Account", "Budget belongs to User or Organisation, tracks spending by categ