  ('map_core', 'Map & Location-Based', 'Location-aware platform where the map is the primary interface. Industry brain defines what is being discovered or tracked on the map. This core defines how location, navigation, and proximity work.', ARRAY['Travel & Lifestyle', 'Real Estate', 'Transport & Logistics']::text[], '{"archetype_id": "map_core", "archetype_name": "Map & Location-Based", "description": "Location-aware platform where the map is the primary interface. Industry brain defines what is being discovered or tracked on the map. This core defines how location, navigation, and proximity work.", "valid_industries": ["Travel & Lifestyle", "Real Estate", "Transport & Logistics"], "icon_pack": {"default_library": {"name": "Lucide", "variant": "Rounded line", "url": "https://lucide.dev"}, "industry_overrides": {"Real Estate": {"name": "Material Symbols", "variant": "Outlined", "url": "https://fonts.google.com/icons"}, "Transport & Logistics": {"name": "Material Symbols", "variant": "Sharp", "url": "https://fonts.google.com/icons"}}, "core_nav_icons": ["home", "search", "map", "heart", "user", "bell", "list", "compass", "arrow-back", "filter"], "core_domain_icons": ["map-pin", "navigation", "compass", "route", "layers", "locate", "zoom-in", "flag", "star", "share-2"]}, "landing_page": {"sections": [{"id": "hero", "generates_images": true}, {"id": "map_preview", "generates_images": true}, {"id": "pricing", "generates_images": false}, {"id": "cta_footer", "generates_images": false}]}, "core_entities": {"entities": ["User", "Location", "Place", "Route", "Pin", "Review", "CheckIn", "Notification", "Search", "Category", "Tracking", "Address"], "relationships": ["User has a current Location", "Place has a Location and belongs to a Category", "Pin is placed by User on the map — saved or custom", "Route connects two or more Locations", "Review belongs to User, written about a Place", "CheckIn belongs to User at a Place", "Tracking belongs to a moving entity (driver, shipment, delivery) with a live Location", "Address is a resolved Location — street, city, coordinates", "Search returns Places near a Location", "Notification belongs to User, triggered by proximity or tracking events"]}, "tiers": {"mvp": {"tier": "MVP", "description": "Core map — discover places, search by location, view detail, get directions.", "screen_count": 8, "primary_flows": ["Open app → map loads at current location → browse nearby places → tap pin → view place detail → get directions", "Search location or place → results on map and list → tap result → detail → directions", "Save place → view saved places → navigate to saved place"], "secondary_flows": ["Share location", "Report incorrect place", "Filter by category", "View place reviews"], "screens": [{"id": "map_home", "name": "Map Home", "purpose": "Primary map view — current location, nearby places, search", "visual": "Full-screen map. Current location dot. Place pins. Search bar at top. Category chips.", "entities": ["Location", "Place", "Pin"], "actions": ["View current location", "Tap place pin", "Search location", "Filter by category", "Zoom and pan", "Toggle map style", "List view toggle"]}, {"id": "place_detail", "name": "Place Detail", "purpose": "Full place information — photos, details, reviews, actions", "visual": "Slides up from bottom. Place photos. Name and category. Rating. Details. Actions row.", "entities": ["Place", "Review", "Location"], "actions": ["View photos", "Get directions", "Save place", "Share place", "Call place", "View website", "Read reviews", "Report place"]}, {"id": "search", "name": "Search", "purpose": "Search places, addresses, and categories", "visual": "Search bar. Recent searches. Category shortcuts. Results list with map pins.", "entities": ["Place", "Address", "Category"], "actions": ["Type to search", "Recent searches", "Category shortcut", "Tap result — show on map and open detail"]}, {"id": "directions", "name": "Directions / Navigation", "purpose": "Route from current location to destination", "visual": "Route on map. Step-by-step panel. Mode selector — drive, walk, transit, bike. ETA.", "entities": ["Route", "Location", "Address"], "actions": ["View route on map", "Select transport mode", "Start navigation", "View step by step", "View ETA", "View alternative routes"]}, {"id": "navigation_active", "name": "Active Navigation", "purpose": "Turn-by-turn navigation full screen", "visual": "Map fills screen. Current instruction prominent. Next turn. ETA. End navigation.", "entities": ["Route", "Location"], "actions": ["Follow turn by turn", "View next instruction", "View ETA", "Mute voice guidance", "End navigation", "Report incident"]}, {"id": "saved_places", "name": "Saved Places", "purpose": "User''s saved and custom pins", "visual": "Saved places list. Custom categories. Map view of saved. Navigate CTA.", "entities": ["Pin", "Place", "User"], "actions": ["View all saved", "Organise into lists", "Navigate to saved place", "Remove saved", "Share saved list"]}, {"id": "profile", "name": "Profile", "purpose": "User profile, reviews written, check-ins", "visual": "Avatar. Stats — reviews, check-ins. Contribution history.", "entities": ["User", "Review", "CheckIn"], "actions": ["View own reviews", "View check-ins", "Edit profile", "View contribution stats"]}, {"id": "settings", "name": "Settings", "purpose": "Map style, location permissions, units, account", "visual": "Settings list. Map style selector. Units — km or miles. Location settings.", "entities": ["User"], "actions": ["Select map style", "Set distance units", "Location permission settings", "Account settings", "Log out"]}], "interaction_patterns": ["Map pins cluster at low zoom — expand on zoom in", "Place detail slides up from bottom as sheet — map stays visible behind", "Current location button — tap to re-centre map on user", "Pin tap — quick preview card slides up — tap card to open full detail", "Route preview — map zooms to fit entire route before starting navigation", "Navigation instruction — large text, icon, and distance remaining", "Long press on map — drop custom pin — option to save or get directions"]}, "startup": {"tier": "Startup", "description": "Full location platform with reviews, check-ins, live tracking, and offline maps.", "screen_count": 14, "primary_flows": ["All MVP flows", "Check in to place → add photo → share → view check-in history", "Track live location of entity → view on map → receive arrival notification", "Write place review with photos → review appears on place detail", "Download offline map → navigate without internet connection"], "secondary_flows": ["All MVP secondary flows", "Share live location with contact", "Report road or map issue", "View nearby events", "Set home and work shortcuts", "Traffic and incident overlay"], "screens": [{"id": "map_home", "name": "Map Home", "purpose": "Full map with traffic, incidents, and live tracking overlays", "visual": "Map. Traffic overlay toggle. Incident icons. Live tracking dots. Search bar.", "entities": ["Location", "Place", "Pin", "Tracking"], "actions": ["All MVP actions", "Toggle traffic layer", "View incident reports", "View live tracked entities"]}, {"id": "place_detail", "name": "Place Detail", "purpose": "Full place with check-in, hours, and popular times", "visual": "Photos. Details. Popular times chart. Check-in CTA. Reviews with photos.", "entities": ["Place", "Review", "Location", "CheckIn"], "actions": ["All MVP actions", "Check in", "View popular times", "View opening hours", "Add photo"]}, {"id": "search", "name": "Search", "purpose": "Advanced search with filters and radius control", "visual": "Search bar. Filters — open now, rating, distance. Radius slider. Results.", "entities": ["Place", "Address", "Category"], "actions": ["All MVP actions", "Filter open now", "Filter by rating", "Set search radius"]}, {"id": "directions", "name": "Directions", "purpose": "Multi-stop directions with traffic and alternatives", "visual": "Route with traffic colour. Multi-stop option. Alternatives. Departure time.", "entities": ["Route", "Location", "Address"], "actions": ["All MVP actions", "Add stop to route", "View traffic delays", "Set departure time", "View alternatives with time difference"]}, {"id": "navigation_active", "name": "Active Navigation", "purpose": "Navigation with traffic rerouting and incident alerts", "visual": "Full screen. Current instruction. Traffic alert banner. Rerouting indicator.", "entities": ["Route", "Location"], "actions": ["All MVP actions", "Accept reroute", "View traffic alert", "Report incident during navigation"]}, {"id": "live_tracking", "name": "Live Tracking", "purpose": "Track moving entity in real time on map", "visual": "Map with tracked entity moving. ETA. Distance. Status. Contact CTA.", "entities": ["Tracking", "Location", "User"], "actions": ["View entity on map", "View ETA", "Contact entity", "Share tracking link", "View tracking history"]}, {"id": "check_in", "name": "Check-In", "purpose": "Check in to a place — add photo and note", "visual": "Place confirm. Photo upload. Note input. Share toggle. Submit.", "entities": ["CheckIn", "Place", "User"], "actions": ["Confirm place", "Add photo", "Add note", "Share to profile", "Submit check-in"]}, {"id": "reviews", "name": "Reviews", "purpose": "Write and browse place reviews", "visual": "Star rating. Review form. Photo upload. Review list with photos.", "entities": ["Review", "Place", "User"], "actions": ["Write review", "Rate place", "Add photos", "Read reviews", "Vote helpful", "Report review"]}, {"id": "saved_places", "name": "Saved Places", "purpose": "Saved places organised into lists — home, work, custom", "visual": "Home and work shortcuts. Custom lists. Map view of list.", "entities": ["Pin", "Place", "User"], "actions": ["All MVP actions", "Set home location", "Set work location", "Create custom list"]}, {"id": "offline_maps", "name": "Offline Maps", "purpose": "Download map areas for offline navigation", "visual": "Map with selection box. Download CTA. Downloaded areas list. Storage meter.", "entities": ["Location", "User"], "actions": ["Select area to download", "Download map", "View downloaded maps", "Delete downloaded map", "Update downloaded map"]}, {"id": "share_location", "name": "Share Location", "purpose": "Share live or static location with contacts", "visual": "Contact selector. Duration selector for live share. Share link. Stop sharing.", "entities": ["User", "Location"], "actions": ["Select contact", "Set share duration", "Generate share link", "Start sharing", "Stop sharing"]}, {"id": "contributions", "name": "Contributions / Profile", "purpose": "User''s reviews, photos, check-ins, and edits", "visual": "Stats bar. Reviews tab. Photos tab. Check-ins tab. Local guide level.", "entities": ["User", "Review", "CheckIn"], "actions": ["View all contributions", "Edit own review", "Delete review", "View check-in map"]}, {"id": "notifications", "name": "Notifications", "purpose": "Proximity alerts, tracking updates, review responses", "visual": "Notification list. Proximity alert. Tracking ETA. Review reply.", "entities": ["Notification", "Place", "Tracking"], "actions": ["View all", "Tap to navigate", "Mark read"]}, {"id": "settings", "name": "Settings", "purpose": "Full settings with offline maps management and tracking privacy", "visual": "Settings list. Offline maps. Location sharing. Map style. Privacy.", "entities": ["User"], "actions": ["All MVP actions", "Offline maps settings", "Location sharing privacy", "Navigation voice settings"]}], "interaction_patterns": ["All MVP interaction patterns", "Traffic colour on route — green fast, amber slow, red stopped", "Reroute banner — faster route found — accept or dismiss", "Live tracking dot pulses — indicates real-time movement", "Popular times bar chart — current time highlighted with live busyness", "Check-in confirm with haptic — short vibration on submit", "Offline map boundary box — drag corners to select area", "Proximity notification — you are near X — tap to view"]}, "scale": {"tier": "Scale", "description": "Full location platform with business listings management, fleet tracking, AR navigation, and admin.", "screen_count": 22, "primary_flows": ["All MVP and Startup flows", "Business claims listing → verifies → manages info, photos, and responses → views analytics", "Fleet operator tracks all vehicles → views routes → sets geofence alerts → receives breach notification", "AR walking navigation — camera view with directional overlays", "Admin manages place database → approves business claims → resolves reported issues"], "secondary_flows": ["All previous secondary flows", "Indoor map navigation", "EV charging station layer", "Accessibility route options", "Heatmap analytics for businesses", "Custom map styling for white-label"], "screens": [{"id": "map_home", "name": "Map Home", "purpose": "Full map with multiple overlay layers and AR toggle", "visual": "Map. Layer toggle panel. AR navigation CTA. Fleet tracking option. Search.", "entities": ["Location", "Place", "Pin", "Tracking"], "actions": ["All Startup actions", "Toggle layers — EV, accessibility, traffic", "Start AR navigation", "Switch to fleet view"]}, {"id": "place_detail", "name": "Place Detail", "purpose": "Full place with claimed business badge and Q&A", "visual": "Photos. Claimed badge. Owner response on reviews. Q&A section. Booking CTA.", "entities": ["Place", "Review", "Location", "CheckIn"], "actions": ["All Startup actions", "View Q&A", "Ask question", "View owner response", "Book directly from map"]}, {"id": "ar_navigation", "name": "AR Navigation", "purpose": "Augmented reality walking directions overlaid on camera", "visual": "Camera view. Direction arrows overlaid. Distance to next turn. Destination pin.", "entities": ["Route", "Location"], "actions": ["Follow AR directions", "Switch to map view", "View destination pin in AR", "End navigation"]}, {"id": "fleet_tracking", "name": "Fleet Tracking", "pu