entities": ["Place", "Review"], "actions": ["Edit business info", "Upload photos", "Respond to reviews", "Answer Q&A", "View analytics", "Post update"]}, {"id": "business_analytics", "name": "Business Analytics", "purpose": "Views, searches, directions clicks, calls, and engagement per listing", "visual": "Views chart. Search terms. Directions requested. Call count. Photo views.", "entities": ["Place"], "actions": ["View views trend", "View search terms", "View directions stats", "View call analytics", "Export report"]}, {"id": "business_claim", "name": "Claim Business Listing", "purpose": "Business owner claims and verifies their listing", "visual": "Search listing. Claim CTA. Verification method selector. Status tracker.", "entities": ["Place", "User"], "actions": ["Search for business", "Claim listing", "Select verification method", "Submit verification", "Track claim status"]}, {"id": "heatmap", "name": "Heatmap Analytics", "purpose": "Show foot traffic density on map — for businesses and admin", "visual": "Map with colour heatmap overlay. Time range selector. Day of week filter.", "entities": ["Location", "Place"], "actions": ["View heatmap", "Select time range", "Filter by day", "Compare periods"]}, {"id": "live_tracking", "name": "Live Tracking", "purpose": "Enterprise tracking with multi-asset and history replay", "visual": "Map. Multi-asset tracking. History replay slider. Status per asset.", "entities": ["Tracking", "Location", "User"], "actions": ["All Startup actions", "Track multiple assets", "Replay route history", "Export tracking data"]}, {"id": "reviews", "name": "Reviews", "purpose": "Reviews with business owner response and verified visit badge", "visual": "Reviews. Verified visit badge. Owner response highlighted. Photo reviews.", "entities": ["Review", "Place", "User"], "actions": ["All Startup actions", "View verified visit reviews", "View owner responses"]}, {"id": "saved_places", "name": "Saved Places", "purpose": "Advanced saved places with shared lists and collaboration", "visual": "Saved lists. Share list. Collaborative list badge. Map view.", "entities": ["Pin", "Place", "User"], "actions": ["All Startup actions", "Share list with collaborators", "Collaborate on list"]}, {"id": "offline_maps", "name": "Offline Maps", "purpose": "Enterprise offline with auto-update and large area support", "visual": "Download manager. Large area support. Auto-update toggle. Storage.", "entities": ["Location", "User"], "actions": ["All Startup actions", "Set auto-update", "Download large region"]}, {"id": "admin_places", "name": "Admin — Place Management", "purpose": "Review reported places, approve claims, manage database", "visual": "Reported places queue. Claim approval queue. Place edit tool. Map preview.", "entities": ["Place", "User"], "actions": ["Review reported places", "Approve or reject claims", "Edit place data", "Remove place", "Merge duplicate places"]}, {"id": "admin_dashboard", "name": "Admin Dashboard", "purpose": "Platform KPIs — searches, active users, reviews, tracking volume", "visual": "KPI cards. Search volume chart. Active users map. Reviews count.", "entities": ["User", "Place", "Review"], "actions": ["View searches", "View active users heat", "View review volume", "View tracking volume", "Export report"]}, {"id": "custom_map_style", "name": "Custom Map Style", "purpose": "White-label map styling for enterprise clients", "visual": "Map style editor. Colour pickers per layer. Preview. Export style JSON.", "entities": ["User"], "actions": ["Customise road colour", "Customise land colour", "Customise water colour", "Preview style", "Export style", "Apply style"]}, {"id": "contributions", "name": "Contributions / Profile", "purpose": "Full contributor profile with level and impact stats", "visual": "Contributor level. Impact stats. Reviews, photos, edits, check-ins tabs.", "entities": ["User", "Review", "CheckIn"], "actions": ["All Startup actions", "View edit history", "View impact score"]}, {"id