  ('marketplace_core', 'Marketplace', 'Two-sided platform connecting buyers and sellers. Industry brain provides the context — what is being bought and sold. This core defines how the marketplace works.', ARRAY['Food & Beverage', 'Retail & Fashion', 'Beauty & Wellness', 'Travel & Lifestyle', 'Real Estate', 'Transport & Logistics', 'Events & Ticketing', 'Education', 'Entertainment & Media']::text[], '{"archetype_id": "marketplace_core", "archetype_name": "Marketplace", "description": "Two-sided platform connecting buyers and sellers. Industry brain provides the context — what is being bought and sold. This core defines how the marketplace works.", "valid_industries": ["Food & Beverage", "Retail & Fashion", "Beauty & Wellness", "Travel & Lifestyle", "Real Estate", "Transport & Logistics", "Events & Ticketing", "Education", "Entertainment & Media"], "icon_pack": {"default_library": {"name": "Lucide", "variant": "Rounded line", "url": "https://lucide.dev"}, "industry_overrides": {"Retail & Fashion": {"name": "Remix Icons", "variant": "Ultra-thin line", "url": "https://remixicon.com"}, "Beauty & Wellness": {"name": "Phosphor Icons", "variant": "Duotone", "url": "https://phosphoricons.com"}, "Real Estate": {"name": "Material Symbols", "variant": "Outlined", "url": "https://fonts.google.com/icons"}, "Events & Ticketing": {"name": "Phosphor Icons", "variant": "Bold filled", "url": "https://phosphoricons.com"}, "Education": {"name": "Phosphor Icons", "variant": "Rounded", "url": "https://phosphoricons.com"}}, "core_nav_icons": ["home", "search", "cart", "heart", "user", "bell", "filter", "list", "arrow-back", "menu"], "core_domain_icons": ["store", "tag", "star", "package", "share", "bookmark", "grid", "sort", "plus", "check"]}, "landing_page": {"sections": [{"id": "hero", "generates_images": true}, {"id": "how_it_works", "generates_images": false}, {"id": "featured_listings_preview", "generates_images": true}, {"id": "pricing", "generates_images": false}, {"id": "cta_footer", "generates_images": false}]}, "core_entities": {"entities": ["User", "Seller", "Listing", "Category", "Cart", "Order", "Review", "Message", "Payment", "Promotion", "Wishlist", "Notification", "Report"], "relationships": ["User can be a Buyer or a Seller (or both)", "Seller owns many Listings", "Listing belongs to one or more Categories", "Cart belongs to User, contains Listings", "Order is created from Cart, belongs to User and Seller", "Review belongs to User, written about a Listing or Seller", "Message belongs to a conversation between User and Seller", "Payment belongs to Order", "Promotion can apply to a Listing or Order", "Wishlist belongs to User, contains Listings", "Notification belongs to User, triggered by Order or Message events", "Report belongs to User, filed against a Listing or Seller"]}, "tiers": {"mvp": {"tier": "MVP", "description": "Core two-sided marketplace — browse, list, buy, sell. Proves supply and demand.", "screen_count": 10, "primary_flows": ["Browse listings → filter by category → view listing detail → add to cart → checkout → order confirmation", "Seller onboard → create listing → publish → manage listings", "Search → results → filter → listing detail → purchase", "View order → track status → receive item → leave review"], "secondary_flows": ["Save listing to wishlist", "Message seller before purchase", "Report a listing", "View seller profile", "Apply promo code at checkout"], "screens": [{"id": "home_browse", "name": "Home / Browse", "purpose": "Discovery — featured listings, categories, search entry", "visual": "Industry brain visual type. Category chips. Featured listings grid or list.", "entities": ["Listing", "Category", "Promotion"], "actions": ["Search listings", "Browse categories", "Tap featured listing", "View promotion banner", "Toggle list or grid view"]}, {"id": "category", "name": "Category / Browse Results", "purpose": "Filtered listing results within a category", "visual": "Listing cards grid or list. Filter and sort