rade", "purpose": "Seller subscription — pro features, lower fees, analytics", "visual": "Plan comparison table. Feature list. Fee breakdown. Upgrade CTA.", "entities": ["Seller"], "actions": ["Compare plans", "Upgrade to pro", "View fee structure", "Cancel plan"]}, {"id": "bulk_listing", "name": "Bulk Listing Management", "purpose": "Power sellers manage many listings at once", "visual": "Data table. Bulk select. Batch edit. Import CSV.", "entities": ["Listing", "Seller"], "actions": ["Bulk select", "Batch price edit", "Bulk publish or unpublish", "Import via CSV", "Export listings"]}, {"id": "create_listing", "name": "Create / Edit Listing", "purpose": "Full listing with variants, authenticity, and escrow settings", "visual": "Step form. Photo upload. Variants. Authenticity toggle. Escrow setting. Publish.", "entities": ["Listing", "Seller", "Category", "Promotion"], "actions": ["All Startup actions", "Enable authenticity verification", "Set escrow requirement"]}, {"id": "promotions", "name": "Promotions", "purpose": "Advanced promotions — flash sales, bundles, affiliate links", "visual": "Promotion types grid. Flash sale countdown. Affiliate link generator.", "entities": ["Promotion", "Listing", "Seller"], "actions": ["Create flash sale", "Create bundle", "Generate affiliate link", "View promotion ROI"]}, {"id": "admin_dashboard", "name": "Admin Dashboard", "purpose": "Platform operator — KPIs, flagged content, seller verification, disputes", "visual": "KPI cards. Flagged listings queue. Dispute queue. Seller verification queue.", "entities": ["User", "Seller", "Listing", "Order"], "actions": ["View platform KPIs", "Review flagged listings", "Approve or reject sellers", "Mediate disputes", "Manage categories"]}, {"id": "admin_users", "name": "Admin — User Management", "purpose": "Search, view, suspend, or ban users and sellers", "visual": "User data table. Search and filter. User detail panel.", "entities": ["User", "Seller"], "actions": ["Search users", "View us