  ('social_core', 'Social & Community', 'Social platform connecting users around shared interests, content, or identity. Industry brain defines the community context. This core defines how social interaction works.', ARRAY['Retail & Fashion', 'Beauty & Wellness', 'Education', 'Fitness & Sport', 'Events & Ticketing', 'Entertainment & Media']::text[], '{"archetype_id": "social_core", "archetype_name": "Social & Community", "description": "Social platform connecting users around shared interests, content, or identity. Industry brain defines the community context. This core defines how social interaction works.", "valid_industries": ["Retail & Fashion", "Beauty & Wellness", "Education", "Fitness & Sport", "Events & Ticketing", "Entertainment & Media"], "icon_pack": {"default_library": {"name": "Phosphor Icons", "variant": "Rounded", "url": "https://phosphoricons.com"}, "industry_overrides": {"Retail & Fashion": {"name": "Remix Icons", "variant": "Ultra-thin line", "url": "https://remixicon.com"}, "Fitness & Sport": {"name": "Tabler Icons", "variant": "Bold line", "url": "https://tabler.io/icons"}, "Entertainment & Media": {"name": "Remix Icons", "variant": "Bold filled", "url": "https://remixicon.com"}}, "core_nav_icons": ["home", "search", "plus-circle", "heart", "user", "bell", "compass", "grid", "arrow-back", "dots"], "core_domain_icons": ["heart", "comment", "share", "bookmark", "camera", "users", "at-sign", "trending", "link", "flag"]}, "landing_page": {"sections": [{"id": "hero", "generates_images": true}, {"id": "community_preview", "generates_images": true}, {"id": "pricing", "generates_images": false}, {"id": "cta_footer", "generates_images": false}]}, "core_entities": {"entities": ["User", "Post", "Comment", "Like", "Follow", "Group", "Message", "Notification", "Story", "Collection", "Event", "Report"], "relationships": ["User creates many Posts", "Post has many Comments and Likes", "User follows other Users", "User joins Groups", "Group contains Posts and Mem