  ('streaming_core', 'Content & Streaming', 'On-demand content consumption platform. Industry brain defines what type of content is consumed. This core defines how content discovery, playback, and progression work.', ARRAY['Education', 'Fitness & Sport', 'Entertainment & Media']::text[], '{"archetype_id": "streaming_core", "archetype_name": "Content & Streaming", "description": "On-demand content consumption platform. Industry brain defines what type of content is consumed. This core defines how content discovery, playback, and progression work.", "valid_industries": ["Education", "Fitness & Sport", "Entertainment & Media"], "icon_pack": {"default_library": {"name": "Remix Icons", "variant": "Bold filled", "url": "https://remixicon.com"}, "industry_overrides": {"Education": {"name": "Phosphor Icons", "variant": "Rounded", "url": "https://phosphoricons.com"}, "Fitness & Sport": {"name": "Tabler Icons", "variant": "Bold line", "url": "https://tabler.io/icons"}}, "core_nav_icons": ["home", "search", "play", "heart", "user", "bell", "library", "compass", "arrow-back", "more"], "core_domain_icons": ["play", "pause", "skip-forward", "volume", "download", "bookmark", "share", "heart", "star", "fullscreen"]}, "landing_page": {"sections": [{"id": "hero", "generates_images": true}, {"id": "content_preview", "generates_images": true}, {"id": "pricing", "generates_images": false}, {"id": "cta_footer", "generates_images": false}]}, "core_entities": {"entities": ["User", "Content", "Series", "Episode", "Category", "Playlist", "Progress", "Subscription", "Download", "Review", "Creator", "Notification"], "relationships": ["Content belongs to a Creator", "Content belongs to one or more Categories", "Series contains many Episodes", "Episode belongs to a Series", "Playlist belongs to User, contains Content", "Progress belongs to User and Content — tracks position and completion", "Subscription belongs to User — defines access level", "Download belongs to User and Content — for offline